arguments.command:
cat /workspace/outputs/wandb-history.jsonl | python3 -c "
import sys, json
rows = [json.loads(l) for l in sys.stdin if l.strip()]
# Summarize training reward (score) vs val acc side by side
print('step | train_score | val_acc  | rollout_corr/kl | entropy | grad_norm | kl_loss')
val_lookup = {}
for r in rows:
    if 'val-core/openai/gsm8k/acc/mean@1' in r:
        s = int(r.get('training/global_step', r.get('step', 0)))
        val_lookup[s] = r['val-core/openai/gsm8k/acc/mean@1']
for r in rows:
    if 'critic/score/mean' in r:
        step = int(r.get('training/global_step', 0))
        score = r['critic/score/mean']
        val = val_lookup.get(step, '-')
        kl_c = r.get('rollout_corr/kl', '?')
        ent = r.get('actor/entropy', '?')
        grad = r.get('actor/grad_norm', '?')
        kl_l = r.get('actor/kl_loss', '?')
        if step % 5 == 0 or step <= 3:
            if isinstance(val, float):
                print(f'{step:4d} | {score:.4f}      | {val:.4f}   | {kl_c:15.2f} | {ent:.4f}   | {grad:.3f}     | {kl_l:.3f}')
            else:
                print(f'{step:4d} | {score:.4f}      | {val}       | {kl_c:15.2f} | {ent:.4f}   | {grad:.3f}     | {kl_l:.3f}')
"

